# Executed at the end of crafts.py (after calendar.py). Shares page(), top(), href(), L(), more_crafts(), SHEET_JS, CRAFTS.
# Keyword Planner worldwide volumes in DEMAND.md C9-C15. All art is generated by our own code (no copied patterns or images).



GCSS = '<style>#gen-prev{background:#fff;border:1px solid #ddd;border-radius:8px;padding:6px;max-width:440px}#gen-prev svg{width:100%;height:auto;display:block}.res-box{background:var(--sheet);border:1px solid var(--line);border-radius:12px;padding:16px}.res-box table{width:100%}.big-n{font-size:1.6rem;font-weight:700}</style>'
# Shared generator runner: draw(W,H) returns SVG body in mm; sets PPsvg/PPsize so SHEET_JS's PPprint/PPdl work.
GEN_JS = r'''<script>(function(){var P={a4:[210,297],letter:[215.9,279.4]};
window.RNG=function(s){s=(s|0)||1;return function(){s=(s*1664525+1013904223)%4294967296;return s/4294967296}};
window.GEN=function(draw,ids){function run(){var pp=document.getElementById("ps-paper"),p=P[pp?pp.value:"letter"],W=p[0],H=p[1];
 var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+W+' '+H+'" width="'+W+'mm" height="'+H+'mm"><rect width="'+W+'" height="'+H+'" fill="#fff"/>'+draw(W,H)+'</svg>';
 document.getElementById("gen-prev").innerHTML=svg;window.PPsvg=svg;window.PPsize=[W,H]}
 ids.concat(["ps-paper"]).forEach(function(i){var e=document.getElementById(i);if(e)e.addEventListener("input",run)});
 window.GENrun=run;run()};
window.V=function(i){return document.getElementById(i).value};window.N=function(i){return +document.getElementById(i).value||0};
})();</script>'''
PAPER = '<div class="field"><label for="ps-paper">Paper</label><select id="ps-paper"><option value="letter">US Letter</option><option value="a4">A4</option></select></div>'
def BTNS(name, reroll=False):
    r = ' <button type="button" class="btn" onclick="document.getElementById(\'g-seed\').value=Math.floor(Math.random()*99999);GENrun()">New design</button>' if reroll else ""
    return f'<div class="btns"><button type="button" class="btn" onclick="PPprint()">Print</button> <button type="button" class="btn" onclick="PPdl(\'{name}\')">Save as image (SVG)</button>{r}</div><p class="note">Print at "Actual size" (not "Fit to page").</p>'
def GEN_PAGE(h1, intro, crumb, quick, form, name, draw_js, ids, reroll=False):
    return top(h1, intro, crumb) + GCSS + f'''
<section style="padding-top:10px"><div class="wrap"><div class="quick"><strong>Quick answer:</strong> {quick}</div></div></section>
<section style="padding-top:0"><div class="wrap tool"><div class="sheet">{form}{PAPER}{BTNS(name, reroll)}</div>
<div class="result"><h2>Preview</h2><div id="gen-prev"></div></div></div></section>
{SHEET_JS}{GEN_JS}<script>GEN(function(W,H){{{draw_js}}},{ids});</script>'''
def CALC_PAGE(h1, intro, crumb, quick, form, js):
    return top(h1, intro, crumb) + GCSS + f'''
<section style="padding-top:10px"><div class="wrap"><div class="quick"><strong>Quick answer:</strong> {quick}</div></div></section>
<section style="padding-top:0"><div class="wrap tool"><div class="sheet">{form}</div><div class="result"><h2>Result</h2><div id="calc-out" class="res-box"></div></div></div></section>
<script>(function(){{function g(i){{return document.getElementById(i)}}function n(i){{return parseFloat(g(i).value)||0}}function run(){{{js}}}
document.querySelectorAll(".sheet input,.sheet select").forEach(function(e){{e.addEventListener("input",run)}});run()}})();</script>'''
def PROSE(file, html):
    return '<section><div class="wrap"><div class="narrow prose">' + L(html) + "</div></div></section>" + more_crafts(file)
SEED = '<div class="field"><label for="g-seed">Design number</label><input type="number" id="g-seed" value="2027" min="1" max="99999"></div>'

