LOOM = [("Newborn", 13, 14, "24 pegs"), ("Baby", 14, 16, "24 to 31 pegs"), ("Toddler/child", 16, 20, "31 pegs"), ("Teen / small adult", 20, 21.5, "36 pegs"), ("Adult", 21.5, 23, "41 pegs"), ("Large adult", 23, 25, "41 pegs (loose fit) or a 48-peg loom")]
