 '<div class="row2"><div class="field"><label for="lk-h">Head circumference</label><input type="number" id="lk-h" value="22" step="0.25"></div><div class="field"><label for="lk-u">Units</label><select id="lk-u"><option value="in">inches</option><option value="cm">cm</option></select></div></div>',
